<?php require_once __DIR__.'/../../middleware/bootstrap.php';require_once __DIR__.'/../../config/database.php';require_admin();$d=body();if($_SERVER['REQUEST_METHOD']==='GET')json_out(['destinations'=>$pdo->query('SELECT * FROM destinations ORDER BY destination_name')->fetchAll()]);if($_SERVER['REQUEST_METHOD']==='DELETE'){$s=$pdo->prepare('DELETE FROM destinations WHERE id=?');try{$s->execute([(int)$d['id']]);}catch(PDOException $e){json_out(['message'=>'Destination has packages; reassign them first.'],409);}json_out(['message'=>'Destination deleted.']);}if(empty($d['destination_name'])||empty($d['country']))json_out(['message'=>'Destination and country are required.'],422);if(!empty($d['id'])){$s=$pdo->prepare('UPDATE destinations SET destination_name=?,country=?,description=?,image=?,status=? WHERE id=?');$s->execute([$d['destination_name'],$d['country'],$d['description']??'',$d['image']??'',$d['status']??'active',$d['id']]);}else{$s=$pdo->prepare('INSERT INTO destinations(destination_name,country,description,image) VALUES(?,?,?,?)');$s->execute([$d['destination_name'],$d['country'],$d['description']??'',$d['image']??'']);}json_out(['message'=>'Destination saved.']);
